contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 firstTime, uint256 amount, uint256 wait) public payable {
        require(amount == 10 ether, "amount must be 10 ether");
        require(address(this).balance >= amount, "not enough balance");

        // Setup: establish an initial pastBlockTime using a valid call.
        // We must make at least one valid fallback call so that the precondition
        // block.timestamp > pastBlockTime can be exercised in the decisive call.
        // The first call uses the default current timestamp; this sets pastBlockTime.
        c.fallback{value: amount}();
        uint256 t0 = c.pastBlockTime();
        uint256 bal0 = address(c).balance;

        // Decisive call: only meaningful if we can pick a future timestamp.
        // block.timestamp is monotonic in the real chain, but the checker runs
        // the whole run() in one transaction, so block.timestamp is constant.
        // Therefore any immediate second call has block.timestamp == pastBlockTime,
        // which makes the require(block.timestamp > pastBlockTime) fail.
        // The general rule we can observe is: the deciding call reverts when
        // block.timestamp is not strictly greater than pastBlockTime, and it
        // does not revert only when it is strictly greater.
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 t1 = c.pastBlockTime();
        uint256 bal1 = address(c).balance;

        // General rule:
        // - Since a second call in the same transaction has the same timestamp,
        //   it must revert unless block.timestamp > pastBlockTime (which cannot
        //   happen here because pastBlockTime was just set to block.timestamp).
        // - If it reverts, pastBlockTime and balance must be unchanged.
        // - If it does not revert, pastBlockTime must have been updated to the
        //   current block.timestamp (and the balance must satisfy the payout rule).
        assert(
            (reverted && t1 == t0 && bal1 == bal0) ||
            (!reverted && t1 >= t0 && bal1 <= bal0 + amount)
        );
    }

    receive() external payable {}
}

