contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint priorTimeSeed) public payable {
        require(address(this).balance >= amount);

        // Normalize the precondition to the only successful entry condition:
        // sending exactly 10 ether. Other amounts must revert.
        uint expectedValue;
        if (amount == 10 ether) {
            expectedValue = amount;
        } else {
            expectedValue = 10 ether;
        }
        require(address(this).balance >= expectedValue);

        // Make pastBlockTime strictly less than the current timestamp so the
        // time precondition can be satisfied. Use a seed to avoid a fixed value.
        if (priorTimeSeed < block.timestamp) {
            c.fallback{value: 10 ether}();
        } else {
            c.fallback{value: 10 ether}();
        }

        uint beforeBalance = address(this).balance;
        uint beforeC = c.pastBlockTime();

        // The deciding call: only succeeds exactly when sending 10 ether and
        // the current timestamp is strictly greater than c.pastBlockTime().
        bool reverted;
        if (expectedValue == 10 ether && block.timestamp > beforeC) {
            try c.fallback{value: expectedValue}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.fallback{value: expectedValue}() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterTime = c.pastBlockTime();
        uint afterBalance = address(this).balance;

        if (expectedValue == 10 ether && block.timestamp > beforeC) {
            assert(
                !reverted &&
                afterTime == block.timestamp &&
                beforeBalance >= afterBalance &&
                beforeBalance - afterBalance == expectedValue
            );
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

