    function run(uint amount, uint64 ts) public payable {
        require(address(this).balance >= amount, "not enough balance");
        require(amount == 10 ether || amount != 10 ether, "always true");

        address self = address(this);
        uint balBefore = self.balance;
        uint cBalBefore = address(c).balance;
        uint ptBefore = c.pastBlockTime();

        bool reverted;
        bool ok;
        if (amount == 10 ether && uint256(ts) > ptBefore) {
            try c.fallback{value: amount}() { ok = true; }
            catch { reverted = true; }
        } else {
            try c.fallback{value: amount}() { ok = true; }
            catch { reverted = true; }
        }

        uint finalCBal = address(c).balance;
