contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint64 timestamp) public payable {
        // The exact ether amount is required for the fallback to consider the call.
        require(amount == 10 ether);

        // Precondition: ensure the fresh contract starts at a timestamp lower than the requested one.
        require(uint64(block.timestamp) < timestamp || uint64(block.timestamp) == timestamp);

        // Advance the block timestamp to the requested value by making a dummy call.
        // We cannot directly set block.timestamp, so we rely on the parameter being ignored
        // and simply drive the state with the required ether amount and current timestamp.

        // Send exactly the required amount; this is a top-level state-changing call.
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule:
        // - The fallback reverts exactly when the new timestamp is not strictly greater than
        //   the previous recorded pastBlockTime.
        // - If it completes, pastBlockTime must equal the current block.timestamp.
        uint observedPast = c.pastBlockTime();
        assert(reverted == (block.timestamp <= observedPast) && (reverted || observedPast == block.timestamp));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run() public payable {
        // Record the prior timestamp before the deciding call.
        uint prior = c.pastBlockTime();

        // The fallback requires exactly 10 ether.
        uint amount = 10 ether;
        require(address(this).balance >= amount);

        bool reverted;
        // The fallback is only callable via a low-level call, not a named function.
        (bool ok, ) = address(c).call{value: amount}("");
        reverted = !ok;

        uint afterTs = c.pastBlockTime();

        // General rule:
        // - reverts iff block.timestamp <= prior, and
        // - on success pastBlockTime is updated to the current block.timestamp.
        // Since prior is 0 on a fresh contract and block.timestamp > 0, the call should succeed
        // and update pastBlockTime, but the assertion also covers the revert case in general.
        assert(reverted == (block.timestamp <= prior) && (reverted || afterTs == block.timestamp));
    }
}

