contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount) public payable {
        // Precondition to exercise the value-dependent success/failure paths.
        // We only need this contract to be able to provide the amount.
        require(address(this).balance >= amount);

        uint256 beforeBalance = address(c).balance;
        uint256 beforePast = c.pastBlockTime();

        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterBalance = address(c).balance;
        uint256 afterPast = c.pastBlockTime();

        bool shouldSucceed = (amount == 10 ether) && (block.timestamp > beforePast);
        if (shouldSucceed) {
            // Successful call: 10 ether entered, pastBlockTime updated to current time.
            // The internal payout condition block.number % 15 == 0 is not asserted here
            // because the balance change also depends on that branch.
            assert(!reverted && afterPast == block.timestamp);
        } else {
            // Reverts occur when the value is not exactly 10 ether, or the timestamp is
            // not strictly newer than the stored pastBlockTime. Revert must leave both
            // the Ether balance and pastBlockTime unchanged.
            assert(reverted && afterBalance == beforeBalance && afterPast == beforePast);
        }
    }

    receive() external payable {}
}

