        // We can only assert on pastBlockTime and reverted.
        // So the rule: reverted == (t <= beforeTime).
        // And if !reverted, pastBlockTime == t.
        // But note: the fallback also requires msg.value == 10 ether. We send exactly amount == 10 ether.
        // So that require is satisfied.

        uint t = block.timestamp;
        bool reverted;
        try c.fallback{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterTime = c.pastBlockTime();

        // Rule: the call reverts exactly when the timestamp is not greater than pastBlockTime.
        // And if it does not revert, pastBlockTime becomes that timestamp.
        assert(reverted == (t <= beforeTime));
        if (!reverted) {
            assert(afterTime == t);
        } else {
            assert(afterTime == beforeTime);
        }
    }

    fallback() external payable {}
    receive() external payable {}
}

