contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint waitTime) public payable {
        require(address(this).balance >= amount);

        // Ensure the contract has at least 10 ether so the 10 ether requirement can potentially be met.
        if (address(this).balance < 10 ether) {
            uint topUp = 10 ether - address(this).balance;
            require(address(this).balance >= topUp);
            (bool ok, ) = address(c).call{value: topUp}("");
            require(ok);
        }

        // Bring the timestamp to a known state: ensure a valid prior call.
        // First, we need enough balance and a valid timestamp. The constructor time is the initial pastBlockTime.
        uint setupAmount = 10 ether;
        require(address(this).balance >= setupAmount);
        (bool setupOk, ) = address(c).call{value: setupAmount}("");
        if (!setupOk) {
            // If the initial timestamp wasn't > stored pastBlockTime, we can still proceed.
            // We'll retry after waiting if waitTime is large enough to make now > stored value.
        }

        // Wait if waitTime is nonzero to make a successful call more likely.
        if (waitTime > 0) {
            uint target = block.timestamp + waitTime;
            uint start = block.timestamp;
            while (block.timestamp < target) {
                // Busy wait, limited to avoid gas issues. If it takes too long, the transaction may revert due to gas.
                if (block.timestamp > target - waitTime) {
                    break;
                }
            }
        }

        uint beforePast = c.pastBlockTime();
        uint beforeBalance = address(c).balance;

        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterPast = c.pastBlockTime();
        uint afterBalance = address(c).balance;

        bool expectedRevert = (amount != 10 ether) || (block.timestamp <= beforePast);
        if (!expectedRevert) {
            // On success, pastBlockTime must be updated to the current timestamp.
            assert(!reverted && afterPast == block.timestamp);
            // Additionally, if the block number is a multiple of 15, the entire balance should be transferred out.
            if (block.number % 15 == 0) {
                assert(address(c).balance == 0);
            } else {
                assert(afterBalance == beforeBalance + amount);
            }
        } else {
            // On failure, nothing should change.
            assert(reverted && afterPast == beforePast && afterBalance == beforeBalance);
        }
    }

    receive() external payable {}
}

