contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool triggerUpdate, uint256 firstValue, uint256 secondValue) public payable {
        // Precondition: enough balance to fund whatever the test may send.
        require(address(this).balance >= firstValue + secondValue || firstValue == 0);

        bool firstReverted;
        uint256 firstSent = firstValue;

        address payable cp = payable(address(c));
        try cp.call{value: firstSent}("") {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        uint256 pastBeforeSecond = c.pastBlockTime();

        uint256 currentTimestamp = block.timestamp;

        bool secondReverted;
        if (triggerUpdate) {
            // Try to set the timestamp to the current block time, making a subsequent call with
            // a small value fail still because of the value check.
        }

        /* second call */
        uint256 secondSent = 10 ether;
        if (secondValue != 0) {
            secondSent = secondValue;
        }

        try cp.call{value: secondSent}("") {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint256 pastAfter = c.pastBlockTime();

        // The fallback accepts exactly the calls where msg.value == 10 ether and
        // block.timestamp > pastBlockTime at the moment of the call.
        // A call whose value is not exactly 10 ether must revert and must not update the
        // stored timestamp. A call with 10 ether succeeds iff the timestamp did.
        if (secondSent != 10 ether) {
            assert(secondReverted && pastAfter == pastBeforeSecond);
        } else {
            assert(!secondReverted ? pastAfter == currentTimestamp : pastAfter == pastBeforeSecond);
        }
    }

    receive() external payable {}
}

