contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint256 amount, uint256 initialTimestamp) public payable {
        require(address(this).balance >= amount);

        // Setup: ensure c's stored timestamp is a known value, if possible.
        // We can only manipulate it via fallback calls, so we first set it to some
        // value by making a successful 10 ether call when possible, then attempt
        // to set it to initialTimestamp. To keep the test general, we simply
        // attempt a first call with initialTimestamp as the block timestamp.

        // We cannot set block.timestamp directly; we just use whatever time.
        // However, we can try to make a call with value amount, and then check.

        // Read before state
        uint256 beforeTimestamp = c.pastBlockTime();

        // Deciding call: call fallback with amount
        bool reverted;
        (bool success, ) = address(c).call{value: amount}("");
        reverted = !success;

        // Expected revert conditions:
        // 1. msg.value != 10 ether
        // 2. block.timestamp <= pastBlockTime
        // Since we cannot know block.timestamp exactly, we use the fact that
        // after a successful call, pastBlockTime should be changed to the
        // current block timestamp, which is >= beforeTimestamp.

        // General rule: if not reverted, then amount == 10 ether and the new
        // pastBlockTime is >= the old one and equals the block timestamp.
        // Also, if reverted due to amount != 10 ether, pastBlockTime unchanged.

        // We can assert the following: reverted == (amount != 10 ether || beforeTimestamp >= block.timestamp)
        // But block.timestamp is current block timestamp, which is after the call?
        // In EVM, block.timestamp is constant during a transaction, so it's the same
        // before and after. So we can use it.

        if (!reverted) {
            // Success requires amount == 10 ether and beforeTimestamp < block.timestamp
            assert(amount == 10 ether && beforeTimestamp < block.timestamp);
            // And the new timestamp must be block.timestamp
            assert(c.pastBlockTime() == block.timestamp);
        } else {
            // Revert if amount != 10 ether OR beforeTimestamp >= block.timestamp
            assert(amount != 10 ether || beforeTimestamp >= block.timestamp);
            // If reverted, pastBlockTime should be unchanged
            assert(c.pastBlockTime() == beforeTimestamp);
        }
    }
}

