contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint priorBlockTime) public payable {
        // Ensure the test contract has enough Ether for the fallback call.
        require(address(this).balance >= amount);

        // Force the initial pastBlockTime to a known value before the deciding call.
        // A first call with exactly 10 ether always succeeds if block.timestamp > 0
        // (the fresh contract has pastBlockTime = 0).
        c.call{value: 10 ether}("");

        // Read the established prior value (should be block.timestamp from the setup call).
        uint prior = c.pastBlockTime();

        // The rule is about a fallback call. We require the precondition needed for it to succeed:
        // msg.value == 10 ether and block.timestamp > prior.
        // Since the parameters cannot directly control block.timestamp, we encode the precondition
        // as a require. If block.timestamp is not greater, the call would revert, but we only assert
        // on the successful case, which is a general rule.
        require(block.timestamp > prior);
        require(amount == 10 ether);

        bool reverted;
        try c.call{value: amount}("") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after_ = c.pastBlockTime();

        // General rule: if the value is exactly 10 ether and the timestamp is strictly greater
        // than the prior pastBlockTime, the fallback call does not revert and pastBlockTime
        // becomes the current block.timestamp.
        assert(!reverted && after_ == block.timestamp && after_ > prior);
    }

    receive() external payable {}
}

